import{_ as n}from"./chunks/27.DgO_Fk5T.js";import{_ as s}from"./chunks/image2.DiCSfv3Q.js";import{_ as l}from"./chunks/image3.CuGNPJKw.js";import{_ as c}from"./chunks/1._Wu06lVH.js";import{_ as a}from"./chunks/0.xVPDiwtD.js";import{_ as d}from"./chunks/2.9ug2zROR.js";import{_ as h}from"./chunks/11.DiIhyeL-.js";import{_ as i}from"./chunks/0.B7TrDeTt.js";import{_ as g}from"./chunks/12.D1pIPcbk.js";import{_ as p}from"./chunks/1.BU1qyW7B.js";import{_ as e}from"./chunks/0.DyB7G7H5.js";import{_ as m}from"./chunks/3.PcdR27wg.js";import{_ as u}from"./chunks/4.ZpmvUIOM.js";import{_ as b}from"./chunks/100.DMbJtyMU.js";import{_ as f}from"./chunks/community.BdKwbEUF.js";import{_,C as y,o as w,c as v,ak as o,E as k}from"./chunks/framework.sbZkgmEx.js";const x="/projects/AiBlock/en/advanced-kit/assets/1.DtPjJzTe.webp",P="/projects/AiBlock/en/advanced-kit/assets/3.B8XyTueB.webp",q="/projects/AiBlock/en/advanced-kit/assets/4.rZVr67o-.webp",J=JSON.parse('{"title":"3.27 Scorpion Mecha Warrior","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.27 Scorpion Mecha Warrior.md","filePath":"docs/3.Creative Builds/3.27 Scorpion Mecha Warrior.md"}'),z={name:"docs/3.Creative Builds/3.27 Scorpion Mecha Warrior.md"};function S(C,t,A,T,j,W){const r=y("Pdf");return w(),v("div",null,[t[0]||(t[0]=o('<h1 id="_3-27-scorpion-mecha-warrior" tabindex="-1">3.27 Scorpion Mecha Warrior <a class="header-anchor" href="#_3-27-scorpion-mecha-warrior" aria-label="Permalink to &quot;3.27 Scorpion Mecha Warrior&quot;">​</a></h1><h2 id="_3-27-1-lesson-introduction" tabindex="-1">3.27.1 Lesson Introduction <a class="header-anchor" href="#_3-27-1-lesson-introduction" aria-label="Permalink to &quot;3.27.1 Lesson Introduction&quot;">​</a></h2><p>Centering on the scorpion mecha warrior robot project, this lesson explores coordinated programming across the drive motor, servo, and ultrasonic sensor. It implements an autonomous combat routine that transitions from patrolling forward to halting and striking when encountering an obstacle. The content examines eight-legged wave gait mechanics and precise servo-driven tail articulation, applies sensor-triggered action sequences, and reinforces multi-actuator scheduling in bio-inspired robotics.</p><img loading="lazy" height="1662" width="1662" src="'+n+'" class="common_img" style="width:400px;"><h2 id="_3-27-2-learning-objectives" tabindex="-1">3.27.2 Learning Objectives <a class="header-anchor" href="#_3-27-2-learning-objectives" aria-label="Permalink to &quot;3.27.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand the locomotion principles of an eight-legged wave gait, appreciating the stability advantages of multi-legged locomotion. Master control logic for triggering combat behaviors via ultrasonic obstacle detection. Consolidate coordinated programming methods uniting motor and servo actuators.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the mechanical structure of the eight-legged scorpion independently, mastering servo calibration and neutral position alignment for the tail mechanism. Program locomotion and tail-strike behaviors. Implement automated combat routines where obstacle detection triggers immediate striking sequences.</p></li><li><p><strong>Thinking Objectives</strong>: Establish state-machine logic for switching between patrol and attack modes. Develop structural design awareness for multi-legged coordination. Reinforce reactive programming principles for rapid sensor-driven responses.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to multi-legged search-and-rescue robots, planetary exploration rovers, and biomimetic robotic insects. Understand the unique mobility advantages of multi-legged walkers across rough terrain. Stimulate enthusiasm for combat robotics and biomimetic mechanism design.</p></li></ol><h2 id="_3-27-3-preparation" tabindex="-1">3.27.3 Preparation <a class="header-anchor" href="#_3-27-3-preparation" aria-label="Permalink to &quot;3.27.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>180° block servo</p></li><li><p>Ultrasonic sensor</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-27-4-hands-on-project" tabindex="-1">3.27.4 Hands-On Project <a class="header-anchor" href="#_3-27-4-hands-on-project" aria-label="Permalink to &quot;3.27.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Scorpion Mecha Warrior, delivering an autonomous biomimetic robot that transitions between forward patrolling and stationary attack behaviors. The system adopts an ultrasonic perception and dual-state switching architecture: the ultrasonic sensor continuously scans ahead, commanding forward patrol travel when obstacle clearance exceeds 12 cm and switching to attack mode when clearance is 12 cm or less. The drive motor powers the eight-legged wave gait linkage, advancing during patrol and halting during attacks. Concurrently, the tail servo regulates stinger posture, keeping it raised and retracted while patrolling and thrusting it forward during an attack. The strike posture holds for 1 s before evaluating distance again, vividly simulating predatory scorpion behavior upon detecting prey.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),k(r,{src:"../../_static/shared/pdf/chapter_3/27.pdf"}),t[1]||(t[1]=o('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the 180° block servo to port <strong>S2</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the ultrasonic sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1300" width="2051" src="'+x+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Ultrasonic sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+s+'" class="common_img" style="width:800px;"><ul><li>Select <strong>180° servo</strong> and <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="121" width="358" src="'+c+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+a+'"></td><td style="text-align:left;">Serves as the main loop container, continuously executing internal code after power-on initialization</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="111" width="360" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+a+'"></td><td style="text-align:left;">Executes only once after the device powers on, used to place startup logic such as hardware initialization and parameter configuration</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="89" width="495" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+i+'"></td><td style="text-align:left;">Initializes the port connection for the ultrasonic sensor</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="112" width="658" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+i+'"></td><td style="text-align:left;">Reads the obstacle distance measured by the ultrasonic sensor on the designated port, in centimeters (cm)</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" width="655" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+e+'"></td><td style="text-align:left;">Directs the 360° block motor on the designated port to rotate continuously forward or in reverse at a custom speed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="91" width="416" src="'+m+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+e+'"></td><td style="text-align:left;">Disables output to the 360° block motor on the designated port, halting rotation immediately</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="88" width="708" src="'+u+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+e+'"></td><td style="text-align:left;">Controls the 180° block servo on the designated port to rotate at a custom speed for a specified duration, continuing immediately to subsequent blocks without waiting if non-delay mode is selected</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="473" width="430" src="'+P+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>Upon startup, the program initializes the ultrasonic sensor interface. In the main loop, the controller monitors clearance ahead: when no obstacle is detected within 12 cm, the Scorpion Mecha Warrior raises its tail and marches forward. When an obstacle appears within 12 cm, the walking motor halts and the tail servo strikes forward.</p></li></ul><img loading="lazy" height="575" width="630" src="'+q+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+b+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1KQ-KBn3OmxCo6xKJkb7ZQZAuPW9brr5t?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-27-5-expansion-and-challenge" tabindex="-1">3.27.5 Expansion and Challenge <a class="header-anchor" href="#_3-27-5-expansion-and-challenge" aria-label="Permalink to &quot;3.27.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Multi-Hit Combo Attack Routine</strong></p><p>Configure the tail servo to alternate rapidly between 0° and 30° three times during an attack sequence, delivering a continuous barrage before holding the final strike posture, paired with flashing LED effects. Practice loop-based timing control and sequential motion programming, extending discussions to combo systems in fighting robots and character attack animations in video games.</p><p><strong>Project 2: Audiovisual Alert Patrol System</strong></p><p>Program the buzzer to emit low-frequency footsteps accompanied by slow green LED pulses while patrolling, transitioning to a high-pitched alarm tone and rapid red flashes during strikes. Practice multi-module synchronization and multi-sensory feedback combining sound with light, extending discussions to security surveillance robots and theme park animatronics.</p><h2 id="_3-27-6-q-a" tabindex="-1">3.27.6 Q&amp;A <a class="header-anchor" href="#_3-27-6-q-a" aria-label="Permalink to &quot;3.27.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why does an eight-legged walking structure provide exceptional stability, and what advantages does it offer over bipedal and quadrupedal gaits?</strong></p><p>Answer: Eight-legged walking achieves high stability because of its <strong>large support polygon and high count of simultaneous ground contacts</strong>. Utilizing a wave-like alternating gait, the eight legs lift and plant in staggered groupings so that four to five feet maintain ground contact at any given instant. These contact points form an expansive geometric base of support that comfortably encloses the center of gravity, virtually eliminating the risk of tipping over. Decreasing the number of legs reduces stability: bipedal gaits have only two contact points forming a line, requiring active dynamic balance, quadrupeds provide three-point support for static stability, and eight-legged configurations offer the greatest stability of all while easily negotiating rugged terrain. In real-world engineering, multi-legged hexapod and eight-legged platforms are widely deployed in rubble and irregular mountainous terrain where wheeled or tracked vehicles cannot operate, with additional legs enhancing obstacle negotiation.</p><p><strong>Question 2: Why does the Scorpion Mecha Warrior halt before executing an attack rather than striking while walking?</strong></p><p>Answer: This design simulates the authentic predatory behavior of scorpions, which pause to stabilize their body before delivering a precise, concentrated sting. Striking while walking would cause chassis vibrations that deflect the stinger trajectory and reduce accuracy. In the software architecture, detecting an obstacle within 12 cm triggers attack mode, where the motor stops and the tail servo articulates in a mutually exclusive state transition. While the program could be adapted to strike on the move as a continuous charge, different behavioral profiles impart distinct character traits to the robot. Modifying control logic allows designers to shape different mechanical behaviors using identical physical hardware.</p><h2 id="_3-27-7-technical-support-and-product-discussion" tabindex="-1">3.27.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-27-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.27.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+f+'" class="common_img" style="width:800px;"></a>',31))])}const Z=_(z,[["render",S]]);export{J as __pageData,Z as default};
